export function buildNightSky(city,k){const {THREE:T,random,texture,mesh,basic}=k;
 const skyTexture=texture(32,512,(c,w,h)=>{const g=c.createLinearGradient(0,0,0,h);g.addColorStop(0,'#02040c');g.addColorStop(.35,'#040b19');g.addColorStop(.5,'#102334');g.addColorStop(.62,'#081722');g.addColorStop(1,'#02050c');c.fillStyle=g;c.fillRect(0,0,w,h);});
 const dome=mesh(new T.SphereGeometry(14000,40,28),new T.MeshBasicMaterial({map:skyTexture,side:T.BackSide,depthWrite:false,fog:false}),city);dome.renderOrder=-10;
 const v=[],col=[];for(let i=0;i<2100;i++){const a=random()*Math.PI*2,y=.12+random()*.88,r=11000,rr=Math.sqrt(1-y*y);v.push(Math.cos(a)*rr*r,y*r,Math.sin(a)*rr*r);const c=new T.Color().setHSL(.1+random()*.55,.08+random()*.25,.38+Math.pow(random(),3)*.5);col.push(c.r,c.g,c.b);}const g=new T.BufferGeometry();g.setAttribute('position',new T.Float32BufferAttribute(v,3));g.setAttribute('color',new T.Float32BufferAttribute(col,3));const stars=new T.Points(g,new T.PointsMaterial({size:1.3,sizeAttenuation:false,vertexColors:true,transparent:true,opacity:.8,fog:false,depthWrite:false}));stars.renderOrder=-8;city.add(stars);
 const moonTex=texture(512,512,(c,w,h)=>{c.fillStyle='#b8bbb5';c.fillRect(0,0,w,h);for(let i=0;i<1700;i++){const x=random()*w,y=random()*h,r=1+Math.pow(random(),3)*32;c.fillStyle=`rgba(54,62,64,${.02+random()*.12})`;c.beginPath();c.arc(x,y,r,0,Math.PI*2);c.fill();c.strokeStyle='rgba(230,235,220,.09)';c.lineWidth=1;c.stroke();}});
 const moon=mesh(new T.SphereGeometry(105,48,32),new T.MeshBasicMaterial({map:moonTex,color:'#d6e0d7',fog:false,toneMapped:false}),city,5700,1300,-6300);moon.rotation.y=1.2;
 const haloTex=texture(128,128,(c)=>{const g=c.createRadialGradient(64,64,2,64,64,64);g.addColorStop(0,'rgba(160,190,220,.16)');g.addColorStop(.3,'rgba(115,158,201,.07)');g.addColorStop(1,'rgba(115,158,201,0)');c.fillStyle=g;c.fillRect(0,0,128,128);});const halo=new T.Sprite(new T.SpriteMaterial({map:haloTex,color:'#b6d5e8',transparent:true,depthWrite:false,fog:false}));halo.position.copy(moon.position);halo.scale.set(1200,1200,1);city.add(halo);k.animations.push(time=>{stars.rotation.y=Math.sin(time*.035)*.002;stars.material.opacity=.78+Math.sin(time*.11)*.025;});return{dome,moon};}
